# -*- coding: utf-8 -*-
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>四人飞行棋游戏</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Arial', sans-serif;
            background-color: #f0f0f0;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            padding: 20px;
        }

        .game-container {
            width: 100%;
            max-width: 900px;
            background-color: white;
            border-radius: 10px;
            padding: 20px;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
        }

        .game-board {
            display: grid;
            grid-template-columns: 1fr 1fr;
            grid-template-rows: 1fr 1fr;
            gap: 20px;
            min-height: 600px;
            margin-bottom: 30px;
        }

        .player-area {
            border-radius: 10px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 24px;
            font-weight: bold;
            color: white;
            text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
            border: 3px solid rgba(0, 0, 0, 0.2);
        }

        .player-red {
            background: linear-gradient(135deg, #FF6B6B, #FF4444);
            grid-column: 1;
            grid-row: 1;
        }

        .player-yellow {
            background: linear-gradient(135deg, #FFD93D, #FFA500);
            grid-column: 2;
            grid-row: 1;
        }

        .player-blue {
            background: linear-gradient(135deg, #4ECDC4, #2E9B9E);
            grid-column: 1;
            grid-row: 2;
        }

        .player-green {
            background: linear-gradient(135deg, #95E1D3, #65B888);
            grid-column: 2;
            grid-row: 2;
        }

        .control-center {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 30px;
            background: linear-gradient(135deg, #667eea, #764ba2);
            border-radius: 10px;
            padding: 40px;
            color: white;
        }

        .dice-button {
            font-size: 18px;
            padding: 15px 40px;
            background-color: white;
            color: #667eea;
            border: none;
            border-radius: 50px;
            cursor: pointer;
            font-weight: bold;
            box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
            transition: transform 0.2s, box-shadow 0.2s;
        }

        .dice-button:hover {
            transform: scale(1.05);
            box-shadow: 0 6px 12px rgba(0, 0, 0, 0.3);
        }

        .dice-button:active {
            transform: scale(0.98);
        }

        .dice-display {
            font-size: 48px;
            font-weight: bold;
            background-color: rgba(255, 255, 255, 0.2);
            padding: 20px 40px;
            border-radius: 10px;
            border: 3px solid white;
            min-width: 120px;
            text-align: center;
        }

        .control-label {
            font-size: 16px;
            letter-spacing: 1px;
        }
    </style>
</head>
<body>
    <div class="game-container">
        <div class="game-board">
            <div class="player-area player-red">红色玩家准备区</div>
            <div class="player-area player-yellow">黄色玩家准备区</div>
            <div class="player-area player-blue">蓝色玩家准备区</div>
            <div class="player-area player-green">绿色玩家准备区</div>
        </div>

        <div class="control-center">
            <div class="control-label">🎲 掷骰子控制面板</div>
            <button class="dice-button" id="diceButton">掷骰子</button>
            <div class="control-label">当前点数：</div>
            <div class="dice-display" id="diceValue">-</div>
        </div>
    </div>

    <script>
        # -*- coding: utf-8 -*-
        // AI-Assisted: Initial draft generated by Claude Code; reviewed and modified by author.

        function rollDice() {
            const diceValue = Math.floor(Math.random() * 6) + 1;
            const diceDisplay = document.getElementById('diceValue');
            diceDisplay.textContent = diceValue;

            const button = document.getElementById('diceButton');
            button.disabled = true;
            setTimeout(function() {
                button.disabled = false;
            }, 500);
        }

        document.getElementById('diceButton').addEventListener('click', rollDice);
    </script>
</body>
</html>
